def LCS(s1, s2): 
    m = len(s1) 
    n = len(s2)

    # dp ویلیوز کو اسٹور کرنے کے لیے ارے (array) کی ڈکلیریشن 
    L = [[None]*(n + 1) for _ in range(m + 1)] 

    """مندرجہ ذیل اقدامات bottom up طریقے سے L[m + 1][n + 1] بناتے ہیں 
    نوٹ: L[i][j] میں X[0..i-1] اور Y[0..j-1] کے LCS کی لمبائی شامل ہے"""
    for i in range(m + 1): 
        # پچھلی رو تمام زیرو ہے، 
        # کیونکہ ان کا استعمال کرتے ہوئے کوئی مشترکہ سیکوئنس نہیں بنایا جا سکتا 
        for j in range(n + 1): 
            # تمام روز کے پہلے کالمز 0 ہیں 
            if i == 0 or j == 0 : 
                L[i][j] = 0
            elif s1[i-1] == s2[j-1]: 
                L[i][j] = L[i-1][j-1]+1
            else: 
                L[i][j] = max(L[i-1][j] , L[i][j-1]) 

    # L[m][n] میں X[0..n-1] اور Y[0..m-1] کے LCS کی لمبائی شامل ہے 
    return L[m][n]

