MergeSort(A, startIndex, endIndex):
    // اگر ارے میں صرف ایک عنصر ہے، تو واپس جائیں
    if startIndex == endIndex:
        return

    middleIndex = (startIndex + endIndex) / 2

    // ارے کے بائیں حصے کو ترتیب دیں
    MergeSort(A, startIndex, middleIndex)

    // ارے کے دائیں حصے کو ترتیب دیں
    MergeSort(A, middleIndex + 1, endIndex)

    // دونوں ترتیب شدہ ارےز کو ضم کریں
    Merge(A, startIndex, endIndex)

Merge(A, startIndex, endIndex):
    middleIndex = (startIndex + endIndex) / 2
    leftIndex = startIndex
    rightIndex = middleIndex + 1

    // ترتیب شدہ ارے کو رکھنے کے لیے عارضی ارے
    tempArray[]

    // ارے کے دونوں حصوں میں دہرائیں
    for i in range(startIndex, endIndex+1):
        // اگر بائیں حصے کی تکرار مکمل ہو گئی ہے، تو دائیں حصے سے شامل کریں
        if leftIndex > middleIndex:
            tempArray[i] = A[rightIndex]
            rightIndex++

        // اگر دائیں حصے کی تکرار مکمل ہو گئی ہے، تو بائیں حصے سے شامل کریں
        else if rightIndex > endIndex:
            tempArray[i] = A[leftIndex]
            leftIndex++

        // موجودہ عنصر کا موازنہ کریں اور چھوٹے عنصر کو شامل کریں
        else if A[leftIndex] < A[rightIndex]:
            tempArray[i] = A[leftIndex]
            leftIndex++
        else:
            tempArray[i] = A[rightIndex]
            rightIndex++

    // tempArray کو واپس A میں کاپی کریں
    for i in range(startIndex, endIndex+1):
        A[i] = tempArray[i]

