import string

# ٹیکسٹ ڈیٹا اسٹرنگ سے پنکچویشن (رموزِ اوقاف) ہٹانے کے لیے ایک فنکشن کی تعریف کریں
def rem_punct(text):
    no_punct = ""
    for char in text:
        if char not in string.punctuation:
            no_punct = no_punct + char
    return no_punct

# ٹیکسٹ ڈیٹا اسٹرنگ میں الفاظ کی تعداد گننے کے لیے ایک فنکشن کی تعریف کریں
def word_count(words):
    count = 0
    for word in words.split():
        count+=1
    return count

# الفاظ کی اوسط لمبائی کے حساب کے لیے ایک فنکشن کی تعریف کریں
def avg_word_length(words):
    count = 0
    total_length = 0
    for word in words.split():
        total_length += len(word)
        count+=1
    return total_length/count

